  const m = VERSION_RE.exec(str.trim());
  if (!m) return null;
  return { nums: [BigInt(m[1]), BigInt(m[2]), BigInt(m[3])], pre: m[4] ? m[4].split('.') : [] };
}

function compareIdent(a, b) {
  const an = /^\d+$/.test(a);
  const bn = /^\d+$/.test(b);
  if (an && bn) {
    const x = BigInt(a);
    const y = BigInt(b);
    return x < y ? -1 : x > y ? 1 : 0;
  }
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function compare(a, b) {
  for (let i = 0; i < 3; i++) {
    if (a.nums[i] !== b.nums[i]) return a.nums[i] < b.nums[i] ? -1 : 1;
  }
  if (!a.pre.length || !b.pre.length) return (b.pre.length > 0) - (a.pre.length > 0);
  for (let i = 0; i < Math.min(a.pre.length, b.pre.length); i++) {
    const c = compareIdent(a.pre[i], b.pre[i]);
    if (c) return c;
  }
  return Math.sign(a.pre.length - b.pre.length);
}

// Parses a possibly partial version into { nums, pre }, where nums holds only
// the specified leading parts (a wildcard ends them). Returns null if invalid.
function parsePartial(str) {
  const m = PARTIAL_RE.exec(str);
  if (!m) return null;
  const nums = [];
  let wild = false;
  for (const part of [m[1], m[2], m[3]]) {
    if (part === undefined || /^[xX*]$/.test(part)) wild = true;
    else if (wild) return null; // e.g. `1.x.3`
    else nums.push(BigInt(part));
